
(function(rootWindow){
function mount(host,bridge){
rootWindow.MementoSortableUI?.clear(host);
host.innerHTML='<div id="memento-hq-preview"><section class="mm-phone" aria-label="Kennis"><div id="mm-status" class="mm-toast" role="status" aria-live="polite"></div><div id="mm-screen"></div></section></div>';
const root=document.getElementById('memento-hq-preview');
const screen=root.querySelector('#mm-screen');
const status=root.querySelector('#mm-status');
rootWindow.MementoKnowledgePortal.hasPending=()=>screen.isConnected&&Boolean(Art?.hasDraft()||screen.querySelector('[name=note]')?.value.trim()||screen.querySelector('#mm-form')&&Array.from(screen.querySelectorAll('input')).some(x=>x.value!==x.defaultValue));
const covers=["data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,"];
const names=['Ontdekken & bewaren','Gezondheid & welzijn','Sport & training','Huis & spullen','Recepten','Werk & leren','Geld & administratie','Vrije tijd & reizen','AI & digitaal','Persoonlijk & groei'];
const subtitles=['Boeken, podcasts en dingen om uit te zoeken','Inzichten, voeding en beter slapen','Trainingskennis en verdieping','Wonen, onderhoud en slimme aankopen','Koken, mealprep en inspiratie','Werkkennis en nieuwe vaardigheden','Naslag, regelzaken en geldkennis','Plannen, plekken en ervaringen','Tools, ideeën en Memento','Reflecties en persoonlijke ontwikkeling'];
const C=rootWindow.MementoKnowledgeCore,Art=rootWindow.MementoKnowledgeCoverUI;
const aliases=[['Ideeën & inspiratie','Inspiratie'],['Persoonlijke naslag','Documenten'],['Levenspad'],['Huis & wonen','Huis & Leven'],['Recepten & creaties'],['TATA Steel'],['Projecten & onderzoek'],['Reizen & ervaringen'],['Memento Development'],['Reflecties & inzichten']];
const sources=aliases.map(group=>(bridge.read().knowledge?.collections||[]).find(c=>group.includes(c.name)));
const recipeTarget='https://www.notion.so/40d8bc13d1af817db914f03400ef8c07';
const seed=()=>names.map((name,i)=>({id:i+1,name,subtitle:subtitles[i],cover:i,link:i===4?recipeTarget:C.notionURL(sources[i]?.externalUrl),hidden:false}));
let items=C.clone(bridge.read().knowledge?.portal?.cards||seed());
// Replace only the obsolete built-in target; keep every user-chosen destination.
for(const card of items)if(card.name==='Recepten'&&C.notionPageId(card.link)==='02f6147c45b14e00b240b02e69536903')card.link=recipeTarget;

function persist(next){try{if(!bridge.write(life=>{C.ensure(life);life.knowledge.portal={version:1,cards:C.clone(next)};C.validate(life);}))throw Error('Opslaan mislukt. Je invoer blijft behouden.');return true;}catch(e){say(e.message);return false;}}
function artwork(x){const source=x.coverFile?{name:x.name,coverFile:x.coverFile,coverFocus:x.coverFocus}:sources[x.cover];return source?'<span class="mm-art">'+Art.cards(source)+'</span>':'';}

let notes=bridge.read().notes.filter(n=>!n.deletedAt&&!n.archived&&C.collectionOf(bridge.read(),n)==='inbox');let nextId=Math.max(10,...items.map(x=>x.id))+1;let pickedCover=0;
let draft=null;let dragging=null;let coverDraft=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>'<span aria-hidden="true">'+({plus:'+',pencil:'✎',ellipsis:'⋯','grip-vertical':'⠿'}[n]||'⌂')+'</span>';
function draw(markup){rootWindow.MementoSortableUI?.clear(screen);screen.innerHTML=markup;Art?.hydrate(screen,rootWindow.MementoKnowledgeStore);}
function say(text){status.textContent=text;}
function overview(){
draft=null;dragging=null;coverDraft=null;Art?.clearPending();
draw(`<h2>Hoofdkwartieren</h2><p>Je kennis. Alles op zijn plek.</p><div class="mm-inbox"><button class="mm-inbox-main cursor-interaction" data-action="inbox"><strong>Inbox</strong><small>${notes.length?notes.length+' snelle notitie'+(notes.length===1?'':'s'):'Even vastleggen, later een plek geven'}</small></button><button class="mm-icon cursor-interaction" data-action="inbox" aria-label="Snelle notitie maken">${icon('plus')}</button></div><div class="mm-row"><strong>Jouw hoofdkwartieren</strong><button class="mm-edit-mode cursor-interaction" data-action="manage">${icon('pencil')} Bewerken</button></div><div class="mm-list">${items.filter(x=>!x.hidden).map(x=>`<article class="mm-hq" style="background-image:linear-gradient(90deg,#08271ff2,#08271f9c 70%,#08271f66),url('${covers[x.cover]}')">${x.link?`<a class="mm-open cursor-interaction" href="${esc(x.link)}">`:`<button class="mm-open cursor-interaction" data-open="${x.id}">`}<strong>${esc(x.name)}</strong><small>${esc(x.subtitle)}</small>${x.link?'</a>':'</button>'}${artwork(x)}<button class="mm-more cursor-interaction" data-edit="${x.id}" aria-label="${esc(x.name)} bewerken">${icon('ellipsis')}</button></article>`).join('')}</div><button class="mm-action mm-secondary mm-full cursor-interaction" data-action="add" style="margin-top:14px">+ Hoofdkwartier toevoegen</button><p class="mm-note">Dagboek en je trainingen blijven op hun eigen plek in Memento.</p>`);
}
function form(id){
const x=items.find(x=>x.id===id);pickedCover=x?x.cover:0;Art?.start(x);coverDraft={name:x?.name||'',icon:'folder',coverFile:x?.coverFile||null,coverFocus:x?.coverFocus??50,dirty:false};
draw(`<h2>${x?'Hoofdkwartier bewerken':'Nieuw hoofdkwartier'}</h2><p>Een eigen ingang naar jouw Notion-pagina.</p><form id="mm-form" data-id="${x?x.id:''}" novalidate><div class="mm-fields"><label>Naam<input name="name" required maxlength="60" placeholder="Bijvoorbeeld: Muziek & creativiteit" value="${esc(x?x.name:'')}"></label><label>Ondertitel<input name="subtitle" maxlength="100" placeholder="Wat bewaar je hier?" value="${esc(x?x.subtitle:'')}"></label><label>Notion-link<input name="link" type="url" placeholder="Plak de link naar je hoofdkwartier" value="${esc(x?x.link:'')}"><small>Kopieer de link van de juiste pagina in Notion.</small></label><div class="mm-cover-area">${Art?.render(coverDraft,"",{customOnly:true})||""}</div></div><div id="mm-error" class="mm-error" role="alert"></div><button type="submit" class="mm-action mm-full cursor-interaction">${x?'Wijzigingen bewaren':'Hoofdkwartier toevoegen'}</button></form><div class="mm-footer"><button class="mm-action mm-secondary cursor-interaction" data-action="home">Annuleren</button>${x?`<button class="mm-action mm-secondary cursor-interaction" data-hide="${x.id}">${x.hidden?'Weer tonen':'Verbergen'}</button>`:''}</div><p class="mm-note">Verbergen verwijdert geen inhoud uit Notion.</p>`);
}
function renderCover(){const area=screen.querySelector('.mm-cover-area');if(area&&coverDraft){area.innerHTML=Art?.render(coverDraft,'',{customOnly:true})||'';Art?.hydrate(area,rootWindow.MementoKnowledgeStore);}}
function manage(){
if(!draft)draft=items.slice();
draw(`<h2>Volgorde bewerken</h2><p>Sleep aan de greep om een hoofdkwartier te verplaatsen.</p><div class="mm-footer"><button class="mm-action cursor-interaction" data-action="save-order">Volgorde opslaan</button><button class="mm-action mm-secondary cursor-interaction" data-action="home">Annuleren</button></div><div id="mm-order-list" role="list" aria-label="Volgorde hoofdkwartieren">${draft.map(x=>`<div class="mm-manage-row" role="listitem" data-order-id="${x.id}" data-moving="${dragging===x.id}"><span>${esc(x.name)}${x.hidden?'<small>Verborgen</small>':''}</span>${x.hidden?`<button class="mm-choice" data-hide="${x.id}">Weer tonen</button>`:''}<button class="mm-drag" data-drag="${x.id}" aria-label="${esc(x.name)} verplaatsen" aria-describedby="mm-drag-help">${icon('grip-vertical')}</button></div>`).join('')}</div><small id="mm-drag-help">Met toetsenbord: focus de greep en gebruik de pijltjes omhoog of omlaag.</small>`);
rootWindow.MementoSortableUI?.mountAll(screen,[{element:screen.querySelector('#mm-order-list'),itemSelector:'.mm-manage-row',idAttr:'data-order-id',handleSelector:'.mm-drag',injectHandle:false,onOrder:ids=>{draft=ids.map(id=>draft.find(c=>String(c.id)===id));manage();return true;}}]);

}
function inbox(){draw(`<h2>Inbox</h2><p>Snel opslaan. Later indelen met AI.</p><form id="mm-note-form"><label>Nieuwe notitie<textarea id="kc-quick-text" name="note" required placeholder="Een idee, link of iets om uit te zoeken…"></textarea></label><button class="mm-action mm-full cursor-interaction" style="margin-top:12px">In inbox bewaren</button></form>${notes.map(n=>`<article class="mm-destination"><strong>${esc(n.title||'Naamloze notitie')}</strong><p>${esc(n.body||'')}</p><div class="mm-note-actions"><button type="button" class="mm-note-ai" data-note-ai="${esc(n.id)}">✧ Verwerken met AI</button><button type="button" class="mm-note-edit" data-note-edit="${esc(n.id)}">Bewerken</button></div></article>`).join('')}<p class="mm-note">Notities blijven hier tot de overdracht naar Notion is bevestigd.</p><button class="mm-action mm-secondary" data-action="home">Terug naar overzicht</button>`);}

screen.addEventListener('click',e=>{
const b=e.target.closest('button');if(!b)return;
if(b.dataset.action){say('');({home:overview,manage,add:()=>form(),inbox,'save-order':()=>{if(draft&&!persist(draft))return;if(draft)items=draft.slice();overview();say('Volgorde opgeslagen.');}}[b.dataset.action]||(()=>{}))();}
if(b.dataset.noteAi){bridge.openAI?.(b.dataset.noteAi);return;}
if(b.dataset.noteEdit){rootWindow.MementoKnowledge?.editNote?.(b.dataset.noteEdit);return;}
if(coverDraft&&b.dataset.kc&&Art?.interact(b.dataset.kc,b.dataset.id,coverDraft,screen,renderCover,say))return;
 if(b.dataset.edit)form(Number(b.dataset.edit));
if(b.dataset.open)say('Dit hoofdkwartier heeft nog geen Notion-link. Gebruik ⋯ om de koppeling toe te voegen.');
if(b.dataset.hide){const x=items.find(x=>x.id===Number(b.dataset.hide)),next=items.map(c=>c===x?{...c,hidden:!c.hidden}:c);if(!persist(next))return;items=next;overview();say(!x.hidden?'Hoofdkwartier verborgen. Je Notion-inhoud blijft bewaard.':'Hoofdkwartier weer zichtbaar.');}
});
screen.addEventListener('input',e=>{if(coverDraft&&e.target.name==='name')coverDraft.name=e.target.value;Art?.changed(e.target,screen);});
screen.addEventListener('change',e=>{if(!coverDraft)return;if(e.target.id==='kc-cover-file-input'){Art?.fileChanged(e.target.files?.[0],coverDraft,rootWindow.MementoKnowledgeStore,renderCover,say);return;}if(e.target.name==='name')renderCover();});
screen.addEventListener('submit',e=>{
e.preventDefault();const f=e.target;
if(f.id==='mm-note-form'){const text=f.elements.note.value.trim();if(text){const note=C.makeNote({title:text.split('\n')[0].slice(0,180),body:text,collectionId:'inbox'},bridge.read());if(!bridge.write(life=>{life.notes.push(note);C.validate(life);})){say('Niet opgeslagen. Je invoer blijft behouden.');return;}notes.unshift(note);inbox();say('Notitie bewaard.');}return;}
if(f.id!=='mm-form')return;
const id=Number(f.dataset.id);const name=f.elements.name.value.trim(),link=f.elements.link.value.trim(),subtitle=f.elements.subtitle.value.trim();
let error='';let url;
if(!name)error='Vul een naam in.';
else if(!link)error='Plak de Notion-link naar dit hoofdkwartier.';
else if(!C.notionPageId(link))error='Gebruik een geldige Notion-paginalink.';

if(!error&&items.some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase()))error='Deze naam bestaat al. Kies een andere naam.';
if(!error&&items.some(x=>x.id!==id&&C.notionPageId(x.link)===C.notionPageId(link)))error='Deze Notion-pagina is al gekoppeld.';
if(error){screen.querySelector('#mm-error').textContent=error;return;}
if(!coverDraft||!Art){screen.querySelector('#mm-error').textContent='De pixelart-editor is niet beschikbaar. Herlaad Memento.';return;}
coverDraft.name=name;
let savedItems=null;
Art.save(coverDraft,{store:rootWindow.MementoKnowledgeStore,core:C,guard:rootWindow.MementoStorageGuard,
 write:(mutate,token)=>bridge.write(life=>{mutate(life);C.validate(life);},token),
 saveCard:(life,data)=>{const next=items.map(c=>({...c}));const card={id:id||nextId,name,link:C.notionURL(link),subtitle,cover:id?items.find(x=>x.id===id).cover:0,hidden:id?items.find(x=>x.id===id).hidden:false,coverFile:data.coverFile,coverFocus:data.coverFocus};if(id)Object.assign(next.find(x=>x.id===id),card);else next.push(card);C.ensure(life).portal={version:1,cards:C.clone(next)};savedItems=next;return card.id;},
 onSaved:()=>{items=savedItems;if(!id)nextId++;overview();say('Opgeslagen.');},
 notify:message=>{const error=screen.querySelector('#mm-error');if(error)error.textContent=message;else say(message);}});
});
overview();
}
rootWindow.MementoKnowledgePortal={mount};
})(window);
